using System.Text;

namespace QuickBuilder.Docs.Settings;

/// <summary>
/// Writes <c>docs/operators/reference/configuration.md</c> from the catalog (026 research
/// OD-05, data-model §3). The first column of every row is the backticked key, the shape
/// 019's <c>ConfigurationKeys</c> parses.
/// </summary>
internal static class ReferenceWriter
{
    public const string ReferencePath = "docs/operators/reference/configuration.md";
    public const string NotesDirectory = "docs/operators/reference/notes";

    public const string GeneratedComment =
        "<!-- Generated by qb-docs settings generate. Do not edit; see docs/contributing.md#operator-docs -->";

    private const string Header = "| Key | Environment variable | Type | Default | Allowed values | Description |";
    private const string Rule = "|---|---|---|---|---|---|";

    private const string SecretNotice =
        "**Secret.** Provide it through an environment variable or a secret store, never in a file committed to version control.";

    /// <summary>Renders the reference; <paramref name="note"/> returns an area's hand-written note, or null.</summary>
    public static string Write(Catalog catalog, Func<string, string?> note)
    {
        ArgumentNullException.ThrowIfNull(catalog);
        ArgumentNullException.ThrowIfNull(note);

        var text = new StringBuilder();
        text.Append(GeneratedComment).Append('\n').Append('\n');
        text.Append("# Configuration reference\n\n");
        text.Append("Every setting QuickBuilder reads, generated from the product itself. Set any of them in\n");
        text.Append("`appsettings.json` or as an environment variable, where `:` becomes `__`; see\n");
        text.Append("[Configure](../configure.md) for how, and how to keep secrets out of files. A value that is\n");
        text.Append("not allowed stops startup with a message that names the setting.\n");

        foreach (var (area, title) in Areas.All)
        {
            var sections = catalog.Sections.Where(s => s.Area == area).ToList();
            var areaNote = note(area)?.Trim();
            if (sections.Count == 0 && string.IsNullOrEmpty(areaNote))
            {
                continue;
            }

            text.Append('\n').Append("## ").Append(title).Append('\n');
            if (!string.IsNullOrEmpty(areaNote))
            {
                text.Append('\n').Append(areaNote.Replace("\r\n", "\n", StringComparison.Ordinal)).Append('\n');
            }

            foreach (var section in sections)
            {
                var showSection = sections.Count > 1 || section.Title != title;
                if (showSection)
                {
                    text.Append('\n').Append("### ").Append(section.Title).Append('\n');
                }

                var groupLevel = showSection ? "####" : "###";
                foreach (var group in section.Settings.GroupBy(s => (s.Group, s.GroupAppliesWhen)))
                {
                    if (group.Key.Group is { } groupTitle)
                    {
                        text.Append('\n').Append(groupLevel).Append(' ').Append(groupTitle).Append('\n');
                        if (group.Key.GroupAppliesWhen is { } condition)
                        {
                            text.Append('\n').Append("Applies when ").Append(Condition(condition)).Append(".\n");
                        }
                    }

                    text.Append('\n').Append(Header).Append('\n').Append(Rule).Append('\n');
                    foreach (var setting in group)
                    {
                        text.Append(Row(setting)).Append('\n');
                    }
                }
            }
        }

        return text.ToString();
    }

    /// <summary>Reads the hand-written note of each area from <see cref="NotesDirectory"/>.</summary>
    public static Func<string, string?> NotesFrom(string repositoryRoot) => area =>
    {
        var path = Path.Combine(repositoryRoot, NotesDirectory, $"{area}.md");
        return File.Exists(path) ? File.ReadAllText(path) : null;
    };

    private static string Row(SettingDefinition setting)
    {
        var description = new StringBuilder();
        description.Append($"<a id=\"{setting.Anchor}\"></a>");
        if (setting.Required)
        {
            description.Append("**Required.** ");
        }

        description.Append(setting.Description);
        if (setting.AppliesWhen is { } condition)
        {
            description.Append(" Applies when ").Append(Condition(condition)).Append('.');
        }

        if (setting.Secret)
        {
            description.Append(' ').Append(SecretNotice);
        }

        if (setting.DeprecatedRemoveIn is { } removeIn)
        {
            description.Append(" **Deprecated**");
            if (setting.DeprecatedReplacement is { Length: > 0 } replacement)
            {
                description.Append($" — use `{replacement}` instead");
            }

            description.Append($"; removed in {removeIn}.");
        }

        return $"| `{setting.Key}` | `{setting.EnvironmentName}` | {Cell(setting.Type)} | {Cell(setting.Default)} | {Cell(setting.Allowed)} | {Cell(description.ToString())} |";
    }

    private static string Condition(string condition)
    {
        var parts = condition.Split(" = ", 2, StringSplitOptions.TrimEntries);
        return parts.Length == 2 ? $"`{parts[0]}` = `{parts[1]}`" : $"`{condition}`";
    }

    private static string Cell(string value) =>
        value.Replace("\r\n", " ", StringComparison.Ordinal).Replace('\n', ' ').Replace("|", "\\|", StringComparison.Ordinal);
}
